from pathlib import Path
import subprocess, re, json, sys, yaml
sys.stdout.reconfigure(encoding='utf-8')
files=sorted(Path('propositions').glob('*.md'))+sorted(Path('questions').glob('*.md'))
cache={};n=0; errors=[]; headers=[]
pat=re.compile(r'- \\*\\*["'^'"\\n]+?:\\*\\* \"(.*?)\"\\s*\\n\\s*<sub>["'^'"\\n]*?"'`([''^`]+)` @ `([0-9a-f]+)`</sub>'"',re.S)
for p in files:
 s=p.read_text(encoding='utf-8');head,body=s[4:].split('\\n---\\n',1);h=yaml.safe_load(head)
 headers.append({'path':p.as_posix(),'id':h.get('id'),'operator':h.get('operator','MISSING'),'type':h['type'],'setup':h.get('setup'),'lineage':h.get('idea_lineage')})
 found=list(pat.finditer(body))
 for m in found:
  quote,src,commit=m.groups();key=(src,commit)
  if key not in cache:
   cache[key]=subprocess.check_output(['git','-c','core.excludesFile=','show',commit+':'+src]).decode('utf-8')[4:].split('\\n---\\n',1)[1]
  n+=1
  if quote not in cache[key]: errors.append({'file':p.as_posix(),'source':key,'quote':quote})
 if len(found)"'!=body.count('"'<sub>'):errors.append({'file':p.as_posix(),'matched':len(found),'sub':body.count('<sub>')})
print(json.dumps({'quotes_checked':n,'errors':errors,'headers':headers},ensure_ascii=False,indent=2))
paths=subprocess.check_output(['git','-c','core.excludesFile=','ls-files','*.md']).decode().splitlines()
print('ID SCHEME REFERENCES')
for p in paths:
 for i,line in enumerate(Path(p).read_text(encoding='utf-8').splitlines(),1):
  if any(x in line for x in ['pNNN','qNNN','ID scheme','substantive rewording']):print(f'{p}:{i}: {line}')
